package com.mockarena.evaluation.infrastructure;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.time.*; import java.util.*;
@Component public class AssessmentSnapshotClient { private final RestClient client; private final String token; public AssessmentSnapshotClient(@Value("${assessment-service.base-url}")String base,@Value("${evaluation.workload-auth.assessment-snapshot-token:}")String token){this.client=RestClient.builder().baseUrl(base).build();this.token=token;} public Snapshot get(UUID attemptId,int position){try{Snapshot s=client.get().uri("/internal/v1/coding-snapshots/attempts/{attemptId}/items/{position}",attemptId,position).header("X-MockArena-Workload-Token",token).retrieve().body(Snapshot.class);if(s==null)throw new IllegalStateException();return s;}catch(RestClientException e){throw new RemoteDependencyException("ASSESSMENT_SNAPSHOT_UNAVAILABLE",e);}} public record Snapshot(UUID attemptId,int globalPosition,UUID questionId,UUID questionVersionId,String programmingLanguage,String sourceCode,Long responseVersion,String sourceFingerprint,boolean unanswered,Instant submittedAt){} }
